package net.officefloor.hq.app.person;

/** A person's grade. */
public enum Grade {
    A, B, C
}
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.util.Arrays;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.SignedInUser;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/grades")
@Validated
public class GradeController {

    /** What the screen shows of a grade: whether it is retired. */
    public record GradeView(Grade grade, boolean retired) {
    }

    /** The grade to retire, as chosen on the screen. */
    public record RetireForm(@NotNull Grade grade) {
    }

    /** The grade to merge and the grade to merge it into, as chosen on the screen. */
    public record MergeForm(@NotNull Grade from, @NotNull Grade into) {
    }

    /** How many people a merge gave the other grade. */
    public record MergeResult(int merged) {
    }

    private final GradeService service;

    public GradeController(GradeService service) {
        this.service = service;
    }

    /** Every grade, in order, with whether it is retired on the sheet. */
    @GetMapping
    public List<GradeView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        Set<Grade> retired = service.retired(sheetId.trim());
        return Arrays.stream(Grade.values()).map((g) -> new GradeView(g, retired.contains(g))).toList();
    }

    /** Retire a grade on the sheet. */
    @PostMapping("/retire")
    public List<GradeView> retire(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid RetireForm form) {
        service.retire(sheetId.trim(), SignedInUser.name(user), form.grade());
        return list(sheetId);
    }

    /** Merge a grade into another on the sheet. */
    @PostMapping("/merge")
    public MergeResult merge(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Valid MergeForm form) {
        return new MergeResult(service.merge(sheetId.trim(), SignedInUser.name(user), form.from(), form.into()).size());
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The sheet's grades and which of them are retired. */
@Service
public class GradeService {

    private final RetiredGradeRepository retired;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final Audit audit;
    private final PersonRepository people;
    private final PersonService persons;
    private final ObjectProvider<SettingService> settings;
    private final Rollup rollup;

    public GradeService(RetiredGradeRepository retired, SheetService sheets, SheetRepository sheetRows, Audit audit,
            PersonRepository people, PersonService persons, ObjectProvider<SettingService> settings,
            Rollup rollup) {
        this.rollup = rollup;
        this.people = people;
        this.persons = persons;
        this.settings = settings;
        this.retired = retired;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.audit = audit;
    }

    /** The grades retired on the sheet. */
    @Transactional(readOnly = true)
    public Set<Grade> retired(String sheetId) {
        return retired.findBySheetId(sheetId).stream().map(RetiredGrade::getGrade).collect(Collectors.toSet());
    }

    /** Retire the grade on the sheet, refused when it is already retired. The people on it keep it. */
    @Transactional
    public Grade retire(String sheetId, String user, Grade grade) {
        sheets.load(sheetId);
        sheetRows.findForUpdate(sheetId);
        if (retired.existsBySheetIdAndGrade(sheetId, grade)) throw alreadyRetired(grade);
        try {
            retired.saveAndFlush(new RetiredGrade(sheetId, grade));
        } catch (DataIntegrityViolationException raced) {
            throw alreadyRetired(grade);
        }
        audit.recordOnCommit("GRADE_RETIRED sheet=" + sheetId + " by=" + user + " grade=" + grade);
        return grade;
    }

    /** Merge a grade into another: everyone whose grade in force on the sheet's today is the merged grade
     *  is given the other from the sheet's today, in list order, each as the person form would edit them.
     *  Refused unless the user is a steward of the sheet, for the same grade twice, and for a retired
     *  grade to merge into; a person who cannot be edited refuses the whole merge. After the people's
     *  own lines, the figures the merge as a whole moved. The people changed. */
    @Transactional
    public List<Person> merge(String sheetId, String user, Grade from, Grade into) {
        sheets.load(sheetId);
        sheetRows.findForUpdate(sheetId);
        if (settings.getObject().roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can merge grades.");
        }
        if (from == into) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Choose two different grades to merge.");
        }
        if (retired.existsBySheetIdAndGrade(sheetId, into)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                    "Grade " + into + " is retired; choose another grade.");
        }
        audit.recordOnCommit("GRADE_MERGED sheet=" + sheetId + " by=" + user + " from=" + from + " into=" + into);
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        LocalDate today = sheets.today(sheetId);
        List<Person> changed = new ArrayList<>();
        for (Person person : people.findInListOrder(sheetId)) {
            if (person.gradeOn(today) != from) continue;
            changed.add(persons.grade(sheetId, user, person.getId(), person.getVersion(), into));
        }
        rollup.recordChanges(user, before);
        return changed;
    }

    private static ResponseStatusException alreadyRetired(Grade grade) {
        return new ResponseStatusException(HttpStatus.CONFLICT, "Grade " + grade + " is already retired.");
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A grade retired on the sheet: no one can be given it any more, while the people on it keep it. */
@Entity
@Table(name = "retired_grade")
public class RetiredGrade {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Enumerated(EnumType.STRING)
    @Column(name = "grade", nullable = false)
    private Grade grade;

    protected RetiredGrade() {
    }

    public RetiredGrade(String sheetId, Grade grade) {
        this.sheetId = sheetId;
        this.grade = grade;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public Grade getGrade() {
        return grade;
    }
}
package net.officefloor.hq.app.person;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface RetiredGradeRepository extends JpaRepository<RetiredGrade, Long> {

    List<RetiredGrade> findBySheetId(String sheetId);

    boolean existsBySheetIdAndGrade(String sheetId, Grade grade);
}
-- The grades retired on a sheet, each at most once. A retired grade can no longer be given to anyone;
-- the people on it keep it.
CREATE TABLE retired_grade (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)   NOT NULL
);
CREATE UNIQUE INDEX retired_grade_once ON retired_grade (sheet_id, grade);
import { HttpClient } from '@angular/common/http';
import { Injectable, computed, effect, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { Grade } from '../people/people-api';

export interface GradeView {
  grade: Grade;
  /** Whether the grade is retired on the sheet: no one can be given it any more. */
  retired: boolean;
}

// The grades of a sheet and which are retired, as the store holds them.
@Injectable({ providedIn: 'root' })
export class GradesApi {
  private readonly http = inject(HttpClient);

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/grades`;
  }

  /** Every grade in order, with whether it is retired. */
  list(sheetId: string): Promise<GradeView[]> {
    return firstValueFrom(this.http.get<GradeView[]>(this.url(sheetId)));
  }

  /** Retire a grade: refused when it is already retired. Answers every grade as it is now. */
  retire(sheetId: string, grade: Grade): Promise<GradeView[]> {
    return firstValueFrom(this.http.post<GradeView[]>(`${this.url(sheetId)}/retire`, { grade }));
  }

  /** Merge a grade into another: refused for the same grade twice, or unless a steward. Answers how
   *  many people were given the other grade. */
  merge(sheetId: string, from: Grade, into: Grade): Promise<{ merged: number }> {
    return firstValueFrom(this.http.post<{ merged: number }>(`${this.url(sheetId)}/merge`, { from, into }));
  }
}

// The active sheet's grades. Each load of a sheet re-reads them from the store.
@Injectable({ providedIn: 'root' })
export class Grades {
  private readonly session = inject(Session);
  private readonly api = inject(GradesApi);

  private readonly state = signal<GradeView[]>([]);
  readonly grades = this.state.asReadonly();
  /** The grades retired on the active sheet: none can be chosen for a new person or in an edit. */
  readonly retired = computed(() => new Set(this.state().filter((g) => g.retired).map((g) => g.grade)));
  /** The refusal of the last loading of the grades, or blank. */
  readonly loadError = signal('');
  /** How many grade merges this screen has made: the people's grades are re-read on each. */
  readonly merges = signal(0);

  constructor() {
    effect(() => {
      const sheet = this.session.loaded();
      this.state.set([]);
      this.loadError.set('');
      if (sheet) void this.load(sheet.id);
    });
  }

  private async load(sheetId: string): Promise<void> {
    try {
      const list = await this.session.reading(this.api.list(sheetId));
      if (this.session.sheet()?.id === sheetId) this.state.set(list);
    } catch {
      if (this.session.sheet()?.id === sheetId) this.loadError.set('The grades could not be loaded.');
    }
  }

  /** Retire a grade on the active sheet; the store's answer replaces the grades. */
  async retire(sheetId: string, grade: Grade): Promise<void> {
    const list = await this.api.retire(sheetId, grade);
    if (this.session.sheet()?.id === sheetId) this.state.set(list);
  }

  /** Merge a grade into another on the active sheet; how many people were given the other grade. */
  async merge(sheetId: string, from: Grade, into: Grade): Promise<number> {
    const result = await this.api.merge(sheetId, from, into);
    this.merges.update((n) => n + 1);
    return result.merged;
  }
}
import { HttpErrorResponse } from '@angular/common/http';
import { Component, effect, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { Session } from '../../core/session';
import { GRADES, Grade } from '../people/people-api';
import { Grades } from './grades-api';

// The sheet's grades, each showing whether it is retired, with a choice to retire one. The people on
// a retired grade keep it, but no one can be given it any more.
@Component({
  selector: 'app-grades',
  imports: [ReactiveFormsModule],
  template: `
    <section aria-labelledby="grades-heading">
      <h2 id="grades-heading">Grades</h2>
      <form [formGroup]="form" (ngSubmit)="submit()" aria-label="Retire a grade">
        <label for="grade-retire-select">Grade</label>
        <select id="grade-retire-select" data-testid="grade-retire-select" formControlName="grade">
          @for (g of choices; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <button type="submit" data-testid="grade-retire" [disabled]="saving()">Retire grade</button>
        @if (error() || store.loadError()) {
          <p role="alert" data-testid="grade-error">{{ error() || store.loadError() }}</p>
        }
      </form>
      <form [formGroup]="mergeForm" (ngSubmit)="merge()" aria-label="Merge a grade into another">
        <label for="grade-merge-from">Merge grade</label>
        <select id="grade-merge-from" data-testid="grade-merge-from" formControlName="from">
          @for (g of choices; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <label for="grade-merge-into">into</label>
        <select id="grade-merge-into" data-testid="grade-merge-into" formControlName="into">
          @for (g of choices; track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <button type="submit" data-testid="grade-merge" [disabled]="merging()">Merge grade</button>
        <span aria-live="polite">
          @if (merged() !== null) {
            Merged <strong data-testid="grade-merged">{{ merged() }}</strong>
          }
        </span>
        @if (mergeError()) {
          <p role="alert" data-testid="grade-error">{{ mergeError() }}</p>
        }
      </form>
      <table aria-label="Grades">
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">Retired</th></tr>
        </thead>
        <tbody>
          @for (g of store.grades(); track g.grade) {
            <tr [attr.data-testid]="'grade-row-' + g.grade">
              <td>{{ g.grade }}</td>
              <td data-testid="grade-retired">{{ g.retired ? 'yes' : 'no' }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class GradesList {
  private readonly session = inject(Session);
  protected readonly store = inject(Grades);

  protected readonly choices = GRADES;
  protected readonly grade = new FormControl<Grade>('A', { nonNullable: true });
  protected readonly form = new FormGroup({ grade: this.grade });
  protected readonly saving = signal(false);
  protected readonly error = signal('');

  protected readonly mergeFrom = new FormControl<Grade>('A', { nonNullable: true });
  protected readonly mergeInto = new FormControl<Grade>('B', { nonNullable: true });
  protected readonly mergeForm = new FormGroup({ from: this.mergeFrom, into: this.mergeInto });
  protected readonly merging = signal(false);
  /** How many people the last merge gave the other grade; null before one, and while one runs. */
  protected readonly merged = signal<number | null>(null);
  protected readonly mergeError = signal('');

  constructor() {
    this.grade.valueChanges.subscribe(() => this.error.set(''));
    this.mergeForm.valueChanges.subscribe(() => this.mergeError.set(''));
    // Each load of a sheet starts the choice afresh.
    effect(() => {
      this.session.loaded();
      this.error.set('');
      this.grade.reset('A', { emitEvent: false });
      this.mergeError.set('');
      this.merged.set(null);
      this.mergeForm.reset({ from: 'A', into: 'B' }, { emitEvent: false });
    });
  }

  protected async submit(): Promise<void> {
    // A second submit before the first has answered is ignored, so it stores one record, not two.
    if (this.saving()) return;
    const sheet = this.session.sheet();
    if (!sheet) return;
    this.error.set('');
    const grade = this.grade.value;
    if (!GRADES.includes(grade)) {
      this.error.set('Choose a grade of A, B or C.');
      return;
    }
    if (this.store.retired().has(grade)) {
      this.error.set(`Grade ${grade} is already retired.`);
      return;
    }
    this.saving.set(true);
    try {
      await this.store.retire(sheet.id, grade);
    } catch (e) {
      if (this.session.sheet()?.id !== sheet.id) return;
      const status = e instanceof HttpErrorResponse ? e.status : 0;
      this.error.set(status === 409 ? `Grade ${grade} is already retired.`
        : status === 403 ? 'Your role may not retire a grade on this sheet.' : 'The grade could not be retired.');
    } finally {
      this.saving.set(false);
    }
  }

  protected async merge(): Promise<void> {
    // A second press before the first has answered is ignored, so the grade is merged once.
    if (this.merging()) return;
    const sheet = this.session.sheet();
    if (!sheet) return;
    this.mergeError.set('');
    this.merged.set(null);
    const from = this.mergeFrom.value;
    const into = this.mergeInto.value;
    if (!GRADES.includes(from) || !GRADES.includes(into)) {
      this.mergeError.set('Choose grades of A, B or C.');
      return;
    }
    if (from === into) {
      this.mergeError.set('Choose two different grades to merge.');
      return;
    }
    this.merging.set(true);
    try {
      const merged = await this.store.merge(sheet.id, from, into);
      if (this.session.sheet()?.id === sheet.id) this.merged.set(merged);
    } catch (e) {
      if (this.session.sheet()?.id !== sheet.id) return;
      const status = e instanceof HttpErrorResponse ? e.status : 0;
      this.mergeError.set(status === 403 ? 'Only a steward can merge grades.'
        : status === 422 ? `Grade ${into} is retired; choose another grade.`
        : status === 400 ? 'Choose two different grades to merge.' : 'The grade could not be merged.');
    } finally {
      this.merging.set(false);
    }
  }
}

