package net.officefloor.hq.app.rollup;

import jakarta.persistence.EntityManager;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.asof.SheetHistory;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Grade;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.SheetParentLink;
import net.officefloor.hq.app.setting.SheetParentRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The figures of a sheet's descendants (its children, the sheets naming it as their parent, then
 * theirs, and so on), added up: the number of people on them and each one's due-total and
 * overdue-total as that sheet shows it; per grade, the due-totals of the people on it today who are not
 * retired (skipping n/a); and per status, how many claims have it. The screen adds the sheet's own figures to make its
 * consolidated figures; each descendant person's figures and name keys are answered too, so the screen can
 * trim the due-total and overdue-total once over the whole tree and count each person once. A sheet with
 * no children has none. The sheet's own figures are answered too, as
 * it shows them. Read as of a date (within the as-of view's transaction, which is rolled back), every
 * sheet of the tree is put back to how it stood at the end of that day, with that date as its today.
 */
@Service
public class ConsolidatedService {

    /** The descendants, in the order found (nearest first), and their figures added up, and the sheet's own;
     *  the totals with two decimals. The grade due-totals by grade, every grade listed; the status counts by
     *  status, every status but DELETED listed. */
    public record Descendants(List<String> sheets, int peopleCount, String dueTotal, String overdueTotal,
            int ownPeopleCount, String ownDueTotal, String ownOverdueTotal, Map<String, String> gradeDueTotals,
            Map<String, Integer> statusCounts, List<PersonFigures> people) {
    }

    /** A descendant's person: their name and aliases as names are compared, their due-total with two
     *  decimals (null for n/a) and their overdue-total with two decimals. */
    public record PersonFigures(List<String> keys, String dueTotal, String overdueTotal) {
    }

    private final SheetParentRepository parents;
    private final Rollup rollup;
    private final SheetHistory history;
    private final EntityManager entityManager;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final SheetRepository sheets;

    public ConsolidatedService(SheetParentRepository parents, Rollup rollup, SheetHistory history,
            EntityManager entityManager, PersonRepository people, ClaimRepository claims, SheetRepository sheets) {
        this.people = people;
        this.claims = claims;
        this.sheets = sheets;
        this.parents = parents;
        this.rollup = rollup;
        this.history = history;
        this.entityManager = entityManager;
    }

    /** The descendants as the store holds them now, or with the date, as every sheet of the tree stood at
     *  the end of that day: only within a transaction that is rolled back (the as-of view's). */
    @Transactional(readOnly = true)
    public Descendants descendantsOf(String sheetId, LocalDate asOf) {
        Set<String> found = descendantSheets(sheetId, asOf);
        int peopleCount = 0;
        BigDecimal due = BigDecimal.ZERO;
        BigDecimal overdue = BigDecimal.ZERO;
        Map<Grade, BigDecimal> gradeDue = new LinkedHashMap<>();
        for (Grade grade : Grade.values()) gradeDue.put(grade, BigDecimal.ZERO);
        Map<ClaimStatus, Integer> statusCount = new LinkedHashMap<>();
        for (ClaimStatus status : ClaimStatus.values()) {
            if (status != ClaimStatus.DELETED) statusCount.put(status, 0);
        }
        List<PersonFigures> treePeople = new ArrayList<>();
        for (String sheet : found) {
            Rollup.Snapshot figures = rollup.snapshot(sheet);
            for (Person person : people.findInListOrder(sheet)) {
                Rollup.Figures theirs = figures.people().get(person.getId());
                if (theirs == null) continue;
                List<String> keys = new ArrayList<>(List.of(Person.keyOf(person.getName())));
                person.getAliases().forEach(alias -> keys.add(Person.keyOf(alias)));
                treePeople.add(new PersonFigures(keys, theirs.dueTotal() == null ? null : text(theirs.dueTotal()),
                        text(theirs.overdueTotal())));
            }
            peopleCount += figures.people().size();
            due = due.add(figures.dueTotal());
            overdue = overdue.add(figures.overdueTotal());
            LocalDate today = sheets.findById(sheet).map(Sheet::getToday).orElse(null);
            for (Person person : people.findInListOrder(sheet)) {
                if (person.isRetired() || today == null) continue;
                Grade grade = person.gradeOn(today);
                Rollup.Figures theirs = figures.people().get(person.getId());
                if (grade == null || theirs == null || theirs.dueTotal() == null) continue;
                gradeDue.merge(grade, theirs.dueTotal(), BigDecimal::add);
            }
            for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheet)) {
                statusCount.computeIfPresent(claim.getStatus(), (s, n) -> n + 1);
            }
        }
        Map<String, String> gradeDueTotals = new LinkedHashMap<>();
        gradeDue.forEach((grade, total) -> gradeDueTotals.put(grade.name(), text(total)));
        Map<String, Integer> statusCounts = new LinkedHashMap<>();
        statusCount.forEach((status, n) -> statusCounts.put(status.name(), n));
        Rollup.Snapshot own = rollup.snapshot(sheetId);
        return new Descendants(new ArrayList<>(found), peopleCount, text(due), text(overdue), own.people().size(),
                text(own.dueTotal()), text(own.overdueTotal()), gradeDueTotals, statusCounts, treePeople);
    }

    /** Per grade, every grade listed, the due-totals of the sheet's people on it today who are not retired
     *  (skipping n/a), with two decimals, as the sheet's summary shows them; read as the store holds it now.
     *  Empty for a sheet that does not exist. */
    @Transactional(readOnly = true)
    public Map<String, String> gradeDueTotalsOf(String sheetId) {
        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
        Map<String, String> totals = new LinkedHashMap<>();
        if (today == null) return totals;
        Rollup.Snapshot figures = rollup.snapshot(sheetId);
        Map<Grade, BigDecimal> gradeDue = new LinkedHashMap<>();
        for (Grade grade : Grade.values()) gradeDue.put(grade, BigDecimal.ZERO);
        for (Person person : people.findInListOrder(sheetId)) {
            if (person.isRetired()) continue;
            Grade grade = person.gradeOn(today);
            Rollup.Figures theirs = figures.people().get(person.getId());
            if (grade == null || theirs == null || theirs.dueTotal() == null) continue;
            gradeDue.merge(grade, theirs.dueTotal(), BigDecimal::add);
        }
        gradeDue.forEach((grade, total) -> totals.put(grade.name(), text(total)));
        return totals;
    }

    /** The sheet's descendants, nearest first: as the store holds them now, or with the date, as every sheet
     *  of the tree stood at the end of that day (only within the as-of view's rolled back transaction). */
    Set<String> descendantSheets(String sheetId, LocalDate asOf) {
        return asOf == null ? descendantsNow(sheetId) : descendantsAsOf(sheetId, asOf);
    }

    private Set<String> descendantsNow(String sheetId) {
        Set<String> found = new LinkedHashSet<>();
        Deque<String> next = new ArrayDeque<>(List.of(sheetId));
        while (!next.isEmpty()) {
            for (SheetParentLink child : parents.findByParentId(next.pop())) {
                if (!child.getSheetId().equals(sheetId) && found.add(child.getSheetId())) next.add(child.getSheetId());
            }
        }
        return found;
package net.officefloor.hq.app.person;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;

/** A grade a person was given, in force from its from-date (or from the beginning of time, when it
 *  has none) until the person's next grade. */
@Entity
@Table(name = "person_grade")
public class PersonGrade {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Enumerated(EnumType.STRING)
    @Column(name = "grade", nullable = false)
    private Grade grade;

    @Column(name = "from_date")
    private LocalDate from;

    /** The sheet's today when the grade was given; null when given before this was kept. */
    @Column(name = "made_on")
    private LocalDate madeOn;

    protected PersonGrade() {
    }

    PersonGrade(Grade grade, LocalDate from, LocalDate madeOn) {
        this.grade = grade;
        this.from = from;
        this.madeOn = madeOn;
    }

    public Grade getGrade() {
        return grade;
    }

    LocalDate getMadeOn() {
        return madeOn;
    }

    void setGrade(Grade grade, LocalDate madeOn) {
        this.grade = grade;
        this.madeOn = madeOn;
    }

    /** Whether the grade was given while the sheet's today was on or before the date. */
    boolean madeBy(LocalDate date) {
        return madeOn == null || !madeOn.isAfter(date);
    }

    /** The date the grade is in force from, or null when it applies from the beginning of time. */
    public LocalDate getFrom() {
        return from;
    }

    /** Whether the grade is in force on or before this date. */
    boolean appliesBy(LocalDate date) {
        return from == null || !from.isAfter(date);
    }

    /** Whether this grade starts later than the other. */
    boolean startsAfter(PersonGrade other) {
        return other.from == null ? from != null : from != null && from.isAfter(other.from);
    }
}

